#pragma once
#include "student_prefix.h"
#include <numeric>
inline void student_prefix_selftest(){
    auto check=[](bool value,const char *what){if(!value)throw std::runtime_error(what);};
    const auto fixture=nlohmann::json::parse(R"FIXTURE({"canonical": "{\"mode\": \"default\", \"language\": \"English\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}", "other_transcript": "{\"mode\": \"default\", \"language\": \"English\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"Entirely different source\"}", "invalid": ["{\"mode\": \"default\", \"language\": \"English\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"} {}", "{\"mode\": \"default\", \"mode\": \"default\", \"language\": \"English\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}", "{\"mode\": \"default\", \"language\": \"English\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji \\ud83d\\ude00 \\u4e2d\\u2028\\u2060.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}", "{\"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"romanize\": false, \"language\": \"English\", \"mode\": \"default\"}", "{\"mode\": \"default\", \"language\": \"English\", \"romanize\": \"false\", \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}", "{\"mode\": \"default\", \"language\": \"English\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [7], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}", "{\"mode\": \"default\", \"language\": \"English\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\", \"extra\": \"bad\"}", "{\"mode\": \"custom\", \"language\": \"English\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}", "{\"mode\": \"default\", \"language\": \"\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}", "{\"mode\":\"default\", \"language\": \"English\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}"], "mutations": ["{\"mode\": \"email\", \"language\": \"English\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}", "{\"mode\": \"default\", \"language\": \"Hindi\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}", "{\"mode\": \"default\", \"language\": \"English\", \"romanize\": true, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}", "{\"mode\": \"default\", \"language\": \"English\", \"romanize\": false, \"instructions\": \"changed\", \"vocabulary\": [\"A \\\"quoted\\\" name\", \"back\\\\slash\", \"\\t\\r\\b\\f\\u0000\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}", "{\"mode\": \"default\", \"language\": \"English\", \"romanize\": false, \"instructions\": \"Preserve literal \\\"transcript\\\": labels, \\\\slashes, newlines\\n and emoji 😀 中 ⁠.\", \"vocabulary\": [\"different\"], \"transcript\": \"SYNTHETIC_PRIVATE_CANARY \\\"transcript\\\": {\\\"mode\\\": \\\"email\\\"}\"}"]})FIXTURE");
    auto first=student_sentinels(fixture.at("canonical"));
    check(first.eligible,"canonical student JSON");
    auto second=student_sentinels(fixture.at("other_transcript"));
    check(first.first==second.first && first.second==second.second && first.metadata==second.metadata,"transcript must not enter sentinels/cache identity");
    check(first.first.find("SYNTHETIC_PRIVATE_CANARY")==std::string::npos && first.second.find("SYNTHETIC_PRIVATE_CANARY")==std::string::npos && first.metadata.find("SYNTHETIC_PRIVATE_CANARY")==std::string::npos,"private canary in cache construction");
    check(nlohmann::json::parse(first.first).at("transcript")=="A" && nlohmann::json::parse(first.second).at("transcript")=="中","sentinel transcript replacement");
    for(const auto & bad:fixture.at("invalid"))check(!student_sentinels(bad).eligible,"noncanonical/invalid input must fall back");
    for(const auto & mutation:fixture.at("mutations"))check(student_sentinels(mutation).eligible && student_sentinels(mutation).metadata!=first.metadata,"every metadata field invalidates cache");
    auto contextual=fixture.at("canonical").get<std::string>();
    const auto location=contextual.find("Preserve literal");
    contextual.insert(location,"Previous text (context only, do NOT repeat it): «SYNTHETIC_PREVIOUS_CANARY». ");
    auto previous=student_sentinels(contextual);
    check(!previous.eligible && previous.first.empty() && previous.second.empty() && previous.metadata.empty(),"previous-piece source must never enter header cache");
    std::vector<int32_t> actual(1500);std::iota(actual.begin(),actual.end(),1);
    auto a=actual,b=actual;b[1101]=-1;
    for(size_t system_size:{1,64,129,511})for(size_t batch:{16,32,64,128,256,512}){
        std::vector<int32_t> system(actual.begin(),actual.begin()+system_size);
        auto candidate=aligned_student_prefix(system,a,b,actual,batch);
        check(!candidate.empty() && candidate.size()<=1024 && (candidate.size()-system_size)%batch==0,"cache endpoint alignment");
        using Chunk=std::pair<size_t,size_t>;
        std::vector<Chunk> baseline,split;
        auto append=[&](auto & output,size_t start,size_t end){for(size_t at=start;at<end;at+=batch)output.emplace_back(at,std::min(end,at+batch));};
        append(baseline,0,system_size);append(baseline,system_size,actual.size());
        append(split,0,system_size);append(split,system_size,candidate.size());append(split,candidate.size(),actual.size());
        check(baseline==split,"prefill chunk/logit boundaries changed");
        auto mismatch=actual;mismatch[candidate.size()-1]=-2;
        check(aligned_student_prefix(system,a,b,mismatch,batch).empty(),"real prompt prefix mismatch must reject");
    }
    std::vector<int32_t> system(actual.begin(),actual.begin()+64);
    auto short_b=a;short_b[70]=-1;
    check(aligned_student_prefix(system,a,short_b,actual,128).empty(),"short metadata fallback");
    check(aligned_student_prefix(system,a,b,actual,0).empty(),"zero batch rejected");
    check(aligned_student_prefix(system,a,b,actual,128,64).empty(),"cap cannot expand");
    PrefixCache cache(4);PrefixIdentity key{"model","template","context",first.metadata};
    check(cache.install(key,system,{1,2}),"synthetic header cache install");
    check(cache.find(key,system,actual),"synthetic header reuse");
    key.system=student_sentinels(fixture.at("mutations").at(0)).metadata;
    check(!cache.find(key,system,actual),"metadata invalidation even with unchanged prefix tokens");
    check(!cache.install(key,system,{1,2,3,4,5}) && cache.bytes()==0,"snapshot cap fail closed");
}
